# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KALBİN DÖRT ODACIKLI YAPISI (SAĞ TARAF KİRLİ - SOL TARAF TEMİZ KAN)</text>\n  <rect x="40" y="48" width="290" height="88" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">SAĞ KULAKÇIK (Üst Sağ Odacık)</text>\n  <text x="185" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Alt ve üst ana toplardamarla vücuttan</text>\n  <text x="185" y="110" text-anchor="middle" font-size="11" fill="#1e3a8a">  gelen kirli (CO2\'li) kanın girdiği odacık</text>\n  <text x="185" y="128" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">↓ Tek yönlü kapakçık ↓</text>\n  <rect x="40" y="148" width="290" height="92" rx="8" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="185" y="172" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">SAĞ KARINCIK (Alt Sağ Odacık)</text>\n  <text x="185" y="194" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kirli kanı Akciğer Atardamarı ile</text>\n  <text x="185" y="210" text-anchor="middle" font-size="11" fill="#1e3a8a">  temizlenmek üzere akciğerlere pompalar</text>\n  <text x="185" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">(Küçük Kan Dolaşımı Başlangıcı)</text>\n  <rect x="370" y="48" width="290" height="88" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="515" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">SOL KULAKÇIK (Üst Sol Odacık)</text>\n  <text x="515" y="94" text-anchor="middle" font-size="11" fill="#7f1d1d">• Akciğerlerde temizlenen (O2\'ce zengin)</text>\n  <text x="515" y="110" text-anchor="middle" font-size="11" fill="#7f1d1d">  kanın Akciğer Toplardamarıyla geldiği yer</text>\n  <text x="515" y="128" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">↓ Tek yönlü kapakçık ↓</text>\n  <rect x="370" y="148" width="290" height="92" rx="8" fill="#fecaca" stroke="#b91c1c" stroke-width="2"/>\n  <text x="515" y="172" text-anchor="middle" font-size="13" font-weight="bold" fill="#7f1d1d">SOL KARINCIK (En Kalın Kaslı Odacık)</text>\n  <text x="515" y="194" text-anchor="middle" font-size="11" fill="#7f1d1d">• Temiz kanı Aort Atardamarı ile tüm</text>\n  <text x="515" y="210" text-anchor="middle" font-size="11" fill="#7f1d1d">  vücut organlarına güçlüce pompalar</text>\n  <text x="515" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">(Büyük Kan Dolaşımı Başlangıcı)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAN DAMARLARI: ATARDAMAR, TOPLARDAMAR VE KILCAL DAMARLAR</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. Atardamarlar</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Görev: Kanı kalpten (karıncık)</text>\n  <text x="40" y="114" font-size="11" fill="#334155">  organlara götüren damarlardır</text>\n  <text x="40" y="138" font-size="11" fill="#334155">• Kan basıncı ve akış hızı</text>\n  <text x="40" y="154" font-size="11" fill="#334155">  en yüksek olan damardır</text>\n  <text x="40" y="178" font-size="11" fill="#334155">• Genelde temiz kan taşır</text>\n  <text x="40" y="196" font-size="11" font-weight="bold" fill="#991b1b">• İstisna: Akciğer Atardamarı</text>\n  <text x="40" y="212" font-size="10.5" fill="#991b1b">  (kirli kan taşır)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kılcal Damarlar</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Görev: Atardamar ile toplardamar</text>\n  <text x="260" y="114" font-size="11" fill="#334155">  arasını bağlayan ince ağdır</text>\n  <text x="260" y="138" font-size="11" fill="#334155">• Kan ile doku hücreleri arasında</text>\n  <text x="260" y="154" font-size="11" fill="#334155">  madde alışverişini (O2, CO2,</text>\n  <text x="260" y="170" font-size="11" fill="#334155">  besin, atık) gerçekleştirir</text>\n  <text x="260" y="196" font-size="11" font-weight="bold" fill="#166534">• Kanın akış hızı en yavaştır</text>\n  <text x="260" y="212" font-size="10.5" fill="#166534">  (alışverişe süre tanımak için)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">3. Toplardamarlar</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Görev: Kanı organlardan kalbin</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  kulakçıklarına geri getirir</text>\n  <text x="480" y="138" font-size="11" fill="#334155">• Kan basıncı en düşük olan</text>\n  <text x="480" y="154" font-size="11" fill="#334155">  damardır (kapakçıklı yapı)</text>\n  <text x="480" y="178" font-size="11" fill="#334155">• Genelde kirli kan taşır</text>\n  <text x="480" y="196" font-size="11" font-weight="bold" fill="#1e40af">• İstisna: Akciğer Toplardamarı</text>\n  <text x="480" y="212" font-size="10.5" fill="#1e40af">  (temiz kan taşır)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BÜYÜK VE KÜÇÜK KAN DOLAŞIMI GÜZERGÂHLARI (FB.7.3.3)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Küçük Kan Dolaşımı (Kalp - Akciğer)</text>\n  <text x="44" y="96" font-size="11" font-weight="bold" fill="#1e40af">Amaç: Kirli kanın akciğerlerde temizlenmesi</text>\n  <text x="44" y="122" font-size="11" fill="#334155">1. Başlangıç: SAĞ KARINCIK (Kirli kan)</text>\n  <text x="44" y="144" font-size="11" fill="#334155">2. Damar: Akciğer Atardamarı (Kirli kan)</text>\n  <text x="44" y="166" font-size="11" fill="#334155">3. Organ: AKCİĞERLER (CO2 verilir, O2 alınır)</text>\n  <text x="44" y="188" font-size="11" fill="#334155">4. Damar: Akciğer Toplardamarı (Temiz kan)</text>\n  <text x="44" y="210" font-size="11" font-weight="bold" fill="#15803d">5. Bitiş: SOL KULAKÇIK (Temiz kan)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. Büyük Kan Dolaşımı (Kalp - Tüm Vücut)</text>\n  <text x="378" y="96" font-size="11" font-weight="bold" fill="#991b1b">Amaç: Organlara O2 ve besin taşınıp atık alınması</text>\n  <text x="378" y="122" font-size="11" fill="#334155">1. Başlangıç: SOL KARINCIK (Temiz kan)</text>\n  <text x="378" y="144" font-size="11" fill="#334155">2. Damar: Aort Atardamarı (Temiz kan)</text>\n  <text x="378" y="166" font-size="11" fill="#334155">3. Organlar: VÜCUT KILCALLARI (Kirlenir)</text>\n  <text x="378" y="188" font-size="11" fill="#334155">4. Damar: Alt ve Üst Ana Toplardamarlar</text>\n  <text x="378" y="210" font-size="11" font-weight="bold" fill="#1d4ed8">5. Bitiş: SAĞ KULAKÇIK (Kirli kan)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
